package com.momcompanion.ai

import com.friendai.CompanionReply

internal object HandlersB {

    private fun String.containsAny(vararg phrases: String): Boolean {
        return phrases.any { contains(it) }
    }
    fun handleNormedNNNN(normalized: String, isRussian: Boolean): CompanionReply? {
        // 1. fond-of-a-good-victoria-sandwich (distinct from victoria sponge in R84 — that was EEEE-8)
        // Using different trigger phrases that don't overlap
        if (normalized.containsAny("a victoria sandwich filled with good raspberry jam is such a classic", "the victoria sandwich has always been my favourite tea cake", "making a victoria sandwich that rises evenly is such a satisfaction", "a perfectly even victoria sandwich is one of the proudest things")) {
            val text = if (isRussian) listOf(
                "Пирожное «Виктория» с малиновым джемом — такая классика! Вы его печёте?",
                "Пирожное «Виктория» всегда было моим любимым к чаю! Расскажите о своём рецепте.",
                "Испечь ровный пирог «Виктория» — такое удовлетворение! Что в вашем рецепте главное?",
                "Идеально ровный пирог «Виктория» — такая гордость! Как вы этого добиваетесь?"
